"""Verify the complete952-role current catalog and exact one-tool delta without changing inherited scientific checks."""
import gzip,json
from setup_deseq2_reference import ROOT,pin
from signac_scan_evidence import unpack,byte_pin
from loftee_catalog import verify_review_extension,loftee_metadata,load_catalog_registry
from catalog_fixed_cohort import verify_fixed_cohort

def verify():
    data=ROOT/'docs/literature/omics-2023-2026';p=json.loads((data/'loftee-catalog-validation.json').read_bytes());assert p['status']=='passed-eight-LOFTEE-primary-roles-and-one-scoped-integration' and (p['new_scoped_integrations'],p['including_existing_adapters'],p['missing_integrations'],p['unrelated_tool_rows_preserved'])==(81,84,250,389) and not p['whole_goal_complete'] and not p['whole_paper_reproduced'] and not p['website_deployed'];assert pin(data/'loftee-catalog-support.zip')==p['archive'];files=unpack(data/'loftee-catalog-support.zip',p)
    for name,value in p['source_pins'].items():assert pin(ROOT/name)==value and byte_pin(files['current-source/'+name])==value
    for name,value in p['parent_proofs'].items():assert pin(ROOT/name)==value
    for name in ['papers.json','tool-inventory.json','summary.json','catalog.md','implementation-plan.md','README.md','WARNINGS.md','loftee-role-coverage.json','loftee-source-audit.json','loftee-prior-reviews.json.gz','loftee-prior-papers.json.gz','loftee-reviews-shared-source-compatibility.json','loftee-render-shared-source-compatibility.json','loftee-root-readme-evolution.json']:assert files['catalog-snapshot/'+name]==(data/name).read_bytes()
    for name in ['literature-review.html','literature-warnings.html']:assert files['site-snapshot/'+name]==(ROOT/'site'/name).read_bytes()
    get=lambda name:json.loads(files[name]);base='build/literature-review/loftee-runtime/';papers=json.loads((data/'papers.json').read_bytes());verify_fixed_cohort(ROOT,data,papers);reviews=json.loads((ROOT/'tools/literature/reviewed-uses.json').read_bytes())['reviews'];verify_review_extension(ROOT,data,reviews);assert len(papers)==250 and len(reviews)==p['reviewed_uses']==952 and sum(len(r.get('supporting_evidence',[])) for r in reviews)==p['supporting_pointers']==328 and sum(len(p['tools']) for p in papers)==p['observations']==2450;old=json.loads(gzip.decompress((data/'loftee-prior-reviews.json.gz').read_bytes()));assert len(old['reviews'])==p['prior_reviews_preserved']==944 and reviews[:944]==old['reviews'];registry=load_catalog_registry(ROOT);registered={r['id'] for r in registry};observed={t['tool_id'] for paper in papers for t in paper['tools']};assert len(registry)==len(registered)==428 and len(observed)==390 and observed<=registered
    before={t['id']:t for t in get(base+'catalog-render-bootstrap-1/before-tool-inventory.json')};current={t['id']:t for t in json.loads((data/'tool-inventory.json').read_bytes())};assert len(current)==390 and {k for k in before if before[k]!=current[k]}=={'loftee'};assert before['loftee']['implementation_status']=='missing';metadata=loftee_metadata(ROOT,data);assert all(current['loftee'][k]==v for k,v in metadata.items()) and metadata['project_adapter_available'] and not metadata['canonical_adapter_available'];counts=json.loads((data/'summary.json').read_bytes())['implementation_status_counts'];assert (counts['native-subset-validated'],counts['upstream-adapter-validated'],counts['missing'])==(17,64,250);assert p['artifact']==json.loads((ROOT/'docs/literature/loftee-workflow-development/VALIDATION.json').read_bytes())['artifact']
    audit=json.loads((data/'loftee-source-audit.json').read_bytes());assert audit['status']=='passed-250-current-primary-source-and-952-role-audit' and (audit['source_XML_hashes_verified'],audit['fulltext_DOIs_verified'],audit['observations_verified'],audit['reviewed_uses_verified'],audit['supporting_pointers_verified'])==(250,250,2450,952,328) and audit['papers_pin']==pin(data/'papers.json') and audit['reviews_pin']==pin(ROOT/'tools/literature/reviewed-uses.json')
    for name,value in audit['source_pins'].items():assert pin(ROOT/name)==value
    gates=get(base+'catalog-scientific-gates-1/COMPLETED.json');assert len(gates['checks'])==p['scientific_gates']==9
    for name,value in gates['source_pins'].items():assert pin(ROOT/name)==value
    context=get(base+'catalog-scientific-gates-1/verify_loftee_review_context.stdout');assert context['current_reviews']==952 and context['prior_reviews_preserved']==944 and context['new_reviews']==8 and not context['scientific_sources_or_frozen_verifiers_changed']
    ui=get(base+'catalog-ui-1/COMPLETED.json');assert ui['page']==pin(ROOT/'site/literature-review.html') and ui['warning_page']==pin(ROOT/'site/literature-warnings.html') and not ui['remote_mutations'];general=get(base+'catalog-ui-1/general/ui-validation.json');focused=get(base+'catalog-ui-1/loftee/loftee-ui-verification.json');assert general['status']==focused['status']=='passed' and len(general['checks'])==p['general_browser_checks']==299 and len(focused['checks'])==p['focused_browser_checks']==5 and not focused['page_errors'] and focused['document_width']<=390
    for name,value in [*ui['source_pins'].items(),*ui['input_pins'].items()]:assert pin(ROOT/name)==value
    assert get(base+'catalog-render-bootstrap-1/COMPLETED.json')['status']=='FAIL2_README_ARCHIVE_PHYSICAL_MEMBER_ASSUMPTION' and get(base+'catalog-render-recovery-1/COMPLETED.json')['status']=='passed-exact-one-tool-LOFTEE-catalog-render-after-retained-bootstrap-failure';workflow=(ROOT/'.github/workflows/pages.yml').read_text(encoding='utf8');assert 'ignore_patterns("literature-review.html", "literature-warnings.html")' in workflow
    lines=(data/'SHA256SUMS').read_text(encoding='utf8').splitlines();manifest={line.split('  ',1)[1]:line.split('  ',1)[0] for line in lines};assert len(manifest)==len(lines) and set(manifest)=={f.name for f in data.iterdir() if f.is_file() and f.name!='SHA256SUMS'} and all(pin(data/n)['sha256']==v for n,v in manifest.items());assert b'\r\n' not in (data/'SHA256SUMS').read_bytes()
    if (ROOT/'build/cli/omicsmatic-0.3.7.jar').exists():assert pin(ROOT/'build/cli/omicsmatic-0.3.7.jar')==p['canonical_executable_unchanged']
    print('Verified250 papers,2450 observations,952 reviewed uses and328 support pointers;81 new scoped integrations/84 including existing adapters;389 other tool rows preserved;9 scientific gates and304 browser checks; whole goal remains active.');return p

if __name__=='__main__':
    if not __debug__:raise RuntimeError('Never disable exact catalog/source checks')
    verify()
